    'custom_bot' => $existingBot ? ['username' => $existingBot['bot_username'], 'channel_id' => $existingBot['bot_channel_id'], 'verified' => (int) $existingBot['is_verified'] === 1] : null,
    'youtube_enabled' => function_exists('youtube_admin_testing') ? (bool) youtube_admin_testing() : false,
